INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('dfa62de5-23b6-5deb-8772-f5d91ff06284', 'hero', 'Bestel aan je tafel', 'Scan de QR-code op je tafel, kies je drankje en wij brengen het.', '{"image_url": "", "button_text": "Bekijk de kaart", "button_link": "/menu", "text_alignment": "left", "overlay_opacity": 0.4}'::jsonb, '{}'::jsonb, 0, true);
