INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('dfa62de5-23b6-5deb-8772-f5d91ff06284', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Hoe bestel ik aan tafel?", "answer": "Scan de QR-code op je tafel. Je bestelling komt meteen op ons scherm achter de toog."}, {"question": "Moet ik meteen betalen?", "answer": "Nee, je betaalt aan de toog wanneer het jou past."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets geschonken of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);